import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"锁与关中断","description":"","frontmatter":{"title":"锁与关中断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lock-irq.md","filePath":"cs/lock-irq.md","lastUpdated":1789023840000}'),m={name:"cs/lock-irq.md"};function h(E,a,A,_,u,B){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="锁与关中断" tabindex="-1">锁与关中断 <a class="header-anchor" href="#锁与关中断" aria-label="Permalink to &quot;锁与关中断&quot;">​</a></h1><div class="epigraph"><p>互斥要用硬件提供的原子能力；在单处理器上，关中断曾经是最短的临界区实现。</p><footer>—— 据 Dijkstra, Solution of a problem in concurrent programming control, CACM 1965；Tanenbaum MOS 整理</footer></div><p><a href="/cs/atomic-rmw">上一课</a>要互斥，还没有手段。<a href="/cs/interrupt-bottom-half">中断下半部</a>与线程调度都会插入临界区中间。缺口是：如何保证「读—改—写锁字」本身不被切开，以及内核里能否用关中断代替锁。本课给出锁与 IRQ 的搭配，不把信号量计数写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件若只用普通存取去做锁（Peterson 在顺序一致下可以），现代多核的弱内存与编译器重排会把它拆掉。硬件提供原子交换或比较并交换，把「尝试获得」收成一条。单核内核里，关中断能阻止下半部抢同一结构；多核上关本地中断挡不住另一 CPU。缺口是分清：<strong>谁与谁并发</strong>。</p><p>本课不写每种体系结构的 <code>lock</code> 前缀，只要求存在原子读改写。</p><p><span class="marginnote">自旋锁忙等，持有期间不能睡。可睡眠锁（互斥锁）在拿不到时走切换。IRQ 上下文只能自旋，因为 ISR 不能调度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户态：用原子指令做自旋或 futex 式睡眠锁。内核：访问「线程与 ISR 共享」的队列时，自旋并关本地 IRQ（或用关底半部），避免锁持有者被同核下半部再抢同一把锁死等。多核仍需自旋，因为关自己的中断不影响对方核。</p>',9)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CS%5B%22%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%20--%3E%20ATOM%5B%22%E5%8E%9F%E5%AD%90%E8%AF%BB%E6%94%B9%E5%86%99%E9%94%81%E5%AD%97%22%5D%0A%20%20ATOM%20--%3E%20SPIN%5B%22%E8%87%AA%E6%97%8B%3A%20IRQ%20%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20ATOM%20--%3E%20SLEEP%5B%22%E7%9D%A1%E7%9C%A0%E9%94%81%3A%20%E7%BA%BF%E7%A8%8B%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20SPIN%20--%3E%20IRQ%5B%22%E5%90%8C%E6%A0%B8%E8%BF%98%E8%A6%81%E5%85%B3%20IRQ%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Dijkstra 1965 证明用户进程可以在无特殊「锁总线」的机器上互斥；当代实现把那条证明换成硬件原子与内存屏障。本课取后者为默认，前者当历史对照。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锁把临界区变成可移植的括号。关中断是更粗的括号：它推迟所有 IRQ，延迟上升，只能罩住极短内核路径。持锁过长会损坏<a href="/cs/scheduling-metrics">调度指标</a>里的响应，也会在实时对照里造成优先级反转：低优先级持锁，高优先级忙等。本课点名，完整协议（优先级继承）不展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入读写锁与 RCU 的全部规则，不把死锁四个条件提前写完。也不给原子指令的微架构延迟表。用户态关中断是不允许的：那是特权。</p><p>读—拷贝—更新等读多写少路径是后话；本课默认写者互斥。</p><p>后课默认：互斥可用原子锁实现；内核共享 IRQ 数据时要关中断或等价屏蔽。需要「计数与等待条件」，下一课信号量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>锁靠硬件原子；单核关中断只能挡同核 IRQ，挡不住多核。</li><li>ISR 不能拿睡眠锁。</li><li>计数式等待是信号量的缺口。</li><li>出处：Dijkstra, <em>CACM</em> 1965；Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const T=i(m,[["render",h]]);export{S as __pageData,T as default};
